// Compiles content/**/*.md into src/content.ts so the workshops ship inside the deployment.
// Runs before every build (npm prebuild); edit the Markdown, never the generated file.
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = new URL("..", import.meta.url).pathname;
const read = (p) => readFileSync(join(root, p), "utf8");

const plays = Object.fromEntries(
  readdirSync(join(root, "content/plays"))
    .filter((f) => f.endsWith(".md"))
    .sort()
    .map((f) => [f.replace(/\.md$/, ""), read(`content/plays/${f}`)])
);

const out = `// GENERATED by scripts/build-content.mjs from content/ — do not edit by hand.
export const PLAYS: Record<string, string> = ${JSON.stringify(plays, null, 2)};

export const METHODOLOGY: string = ${JSON.stringify(read("content/methodology.md"))};
`;

writeFileSync(join(root, "src/content.ts"), out);
console.log(`content: ${Object.keys(plays).length} plays + methodology → src/content.ts`);
